import React, { useState } from 'react';

// Import local logo images
import githubLogo from './images/github.jfif';
import facebookLogo from './images/facebook.jfif';
import googleLogo from './images/google.jfif';
import appleLogo from './images/apple.jfif';

const SignIn = () => {
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false); // State for the checkbox
  const [showFields, setShowFields] = useState(false); // Track visibility of name and password fields

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle sign-in logic here (e.g., API call)
    console.log('Name:', name);
    console.log('Password:', password);
    console.log('Remember Me:', rememberMe);
  };

  // Redirection function
  const redirectTo = (url) => {
    window.location.href = url;
  };

  // Styles
  const containerStyle = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100vh',
    paddingTop: '20px',
  };

  const borderStyle = {
    border: '2px solid #ccc',
    borderRadius: '10px',
    padding: '20px',
    minWidth: '300px',
    width: '100%',
    maxWidth: '400px',
    backgroundColor: '#fff',
  };

  const formStyle = {
    padding: '20px',
    width: '300px',
  };
  const buttonStyle = {
    backgroundColor: '#F27520',
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    borderRadius: '5px',
    cursor: 'pointer',
    width: '50%',
    textAlign: 'center',
  };
  const logosContainerStyle = {
    display: 'flex',
    justifyContent: 'space-around',
    alignItems: 'center',
    marginTop: '20px',
  };
  const logoStyle = {
    width: '40px',
    height: 'auto',
    cursor: 'pointer',
  };
  const linkStyle = {
    display: 'block',
    marginTop: '10px',
    textAlign: 'center',
  };

  // Toggle visibility of name and password fields when the dropdown is clicked
  const handleDropdownClick = () => {
    setShowFields(!showFields); // Toggle the visibility of the name and password fields
  };

  return (
    <div style={containerStyle}>
      <div style={borderStyle}>
        <div style={formStyle}>
          <h2>Sign In</h2>
          <div>
            <select
              value="cadmax" // Fixed value to "Cadmax Login"
              onClick={handleDropdownClick} // Trigger onClick when dropdown is clicked
              required
              disabled // Make the dropdown unchangeable
            >
              <option value="cadmax">Cadmax Login</option>
            </select>
            <br />
          </div>
          <form onSubmit={handleSubmit}>
            {/* Conditionally render name and password fields based on the state */}
            {showFields && (
              <>
                <div>
                  <label>Name:</label>
                  <br />
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Enter your username"
                    required
                  />
                </div>
                <div>
                  <label>Password:</label>
                  <br />
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Enter your password"
                    required
                  />
                </div>
                <div>
                  <input
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                  />
                  <label> Keep me signed in</label>
                </div>
                <br />
                <button type="submit" style={buttonStyle}>Sign In</button>
              </>
            )}
          </form>

          {/* Horizontal Line */}
          <hr style={{ margin: '20px 0' }} />

          {/* Logos Section */}
          <div style={logosContainerStyle}>
            <img
              src={githubLogo}
              alt="GitHub"
              style={logoStyle}
              onClick={() => redirectTo('https://github.com')}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img
              src={facebookLogo}
              alt="Facebook"
              style={logoStyle}
              onClick={() => redirectTo('https://facebook.com')}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img
              src={googleLogo}
              alt="Google"
              style={logoStyle}
              onClick={() => redirectTo('https://google.com')}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img
              src={appleLogo}
              alt="Apple"
              style={logoStyle}
              onClick={() => redirectTo('https://apple.com')}
            />
          </div>

          <div style={linkStyle}>
            No account? <a href="/create-account">Create an account</a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SignIn;
